#!/usr/bin/env python3
"""Run a command under a pty, answer CPR queries, optionally send an answer."""
import os, pty, sys, select, time, signal

cmd = sys.argv[1]
answer = sys.argv[2] if len(sys.argv) > 2 else None
pid, fd = pty.fork()
if pid == 0:
    os.execvp("sh", ["sh", "-c", cmd])

out = b""
sent = False
cpr_time = None
deadline = time.time() + 15
status = None
while time.time() < deadline:
    r, _, _ = select.select([fd], [], [], 0.2)
    if r:
        try:
            data = os.read(fd, 4096)
        except OSError:
            break
        if not data:
            break
        out += data
        while b"\x1b[6n" in out:
            os.write(fd, b"\x1b[1;1R")
            out = out.replace(b"\x1b[6n", b"", 1)
            cpr_time = time.time()
    wpid, st = os.waitpid(pid, os.WNOHANG)
    if wpid == pid:
        status = st
        break
    if (answer and not sent and cpr_time and time.time() - cpr_time > 0.5
            and b"(y/N)" in out):
        os.write(fd, answer.encode())
        sent = True

if status is None:
    try:
        os.kill(pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    try:
        _, status = os.waitpid(pid, 0)
    except ChildProcessError:
        status = 0
# drain
try:
    while True:
        r, _, _ = select.select([fd], [], [], 0.2)
        if not r:
            break
        data = os.read(fd, 4096)
        if not data:
            break
        out += data
except OSError:
    pass
sys.stdout.buffer.write(out)
sys.stdout.buffer.flush()
if os.WIFEXITED(status):
    print("\n[EXIT=%d]" % os.WEXITSTATUS(status))
elif os.WIFSIGNALED(status):
    print("\n[KILLED sig=%d]" % os.WTERMSIG(status))
